import{_ as n,I as i,c as r,o,j as t,J as s,ag as d,a as c}from"./chunks/framework.Vyheyqg9.js";const g=JSON.parse('{"title":"A webhook-to-service integration","description":"","frontmatter":{},"headers":[],"relativePath":"applied-ai/n8n/integration.md","filePath":"applied-ai/n8n/integration.md"}'),l={name:"applied-ai/n8n/integration.md"};function h(p,e,u,m,k,b){const a=i("MermaidDiagram");return o(),r("div",null,[e[0]||(e[0]=t("h1",{id:"a-webhook-to-service-integration",tabindex:"-1"},[c("A webhook-to-service integration "),t("a",{class:"header-anchor",href:"#a-webhook-to-service-integration","aria-label":"Permalink to “A webhook-to-service integration”"},"​")],-1)),e[1]||(e[1]=t("p",null,"Use one small operation: request a refresh of an authorized synthetic note. n8n validates/projects an event and calls an application-owned endpoint. The service maps its credential to scope, checks the source/version and returns a stable local receipt. It does not let an incoming tenant field choose authority or let note text approve a rename.",-1)),s(a,{"encoded-source":"flowchart%20TD%0A%20%20%20%20Hook%5BWebhook%3A%20inbound%20authentication%5D%20--%3E%20Normalize%5BValidate%20and%20project%20event%5D%0A%20%20%20%20Normalize%20--%3E%20Branch%7BSupported%20action%3F%7D%0A%20%20%20%20Branch%20--%3E%7Cno%7C%20Reject%5BFixed%20rejected%20response%5D%0A%20%20%20%20Branch%20--%3E%7Cyes%7C%20HTTP%5BHTTP%20Request%3A%20outbound%20credential%5D%0A%20%20%20%20HTTP%20--%3E%20Service%5BService%3A%20current%20authorization%20and%20idempotency%5D%0A%20%20%20%20Service%20--%3E%20Respond%5BReturn%20correlated%20receipt%20or%20safe%20failure%5D"}),e[2]||(e[2]=d('<h2 id="test-and-production-urls-are-different" tabindex="-1"><span class="hub-section-number">1 </span>Test and production URLs are different <a class="header-anchor" href="#test-and-production-urls-are-different" aria-label="Permalink to “1 Test and production URLs are different”">​</a></h2><p>Configure POST and a specific test path. A Webhook node exposes a test URL for a listening manual execution and a production URL registered when the workflow is published. Copy the URL shown by the installed version; do not hardcode or interchange the two. Production execution data is inspected in execution history rather than the live test canvas. This review publishes neither endpoint. <a href="https://docs.n8n.io/integrations/builtin/core-nodes/n8n-nodes-base.webhook/" target="_blank" rel="noreferrer">Official Webhook behavior</a>.</p><p>The webhook envelope commonly puts submitted JSON under <code>body</code> alongside request metadata. Explicitly select <code>body</code>, validate its allowed fields and project the output. Do not forward request headers/cookies/query parameters, arbitrary URLs, owner fields or source text to the next service. The reference&#39;s raw body is:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;event_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;evt_1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;public&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;revision&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;refresh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A malformed field goes to a controlled validation response before integration I/O. Use an explicit response mode: Respond to Webhook after the service result for a short synchronous demo, or acknowledge durable job acceptance with an operation ID and a separate authorized status lookup. An immediate success response does not prove refresh completion. Bound payload size at ingress as well as after item materialization.</p><h2 id="credentials-have-distinct-scopes" tabindex="-1"><span class="hub-section-number">2 </span>Credentials have distinct scopes <a class="header-anchor" href="#credentials-have-distinct-scopes" aria-label="Permalink to “2 Credentials have distinct scopes”">​</a></h2><p>Inbound webhook authentication decides which sender may trigger the workflow. Outbound HTTP credentials decide what the workflow may request from the service. Configure both in n8n credential records, never literal secrets in expressions, Code, URLs, pinned data or exported workflow JSON. An inbound shared secret is not automatically an end-user identity; the service must map an approved integration identity to its allowed tenant/source set or use a reviewed delegated-user contract.</p><p>For the local recipe use Header Auth. The outbound service expects an Authorization bearer credential for a synthetic integration identity. Store a separate credential for that destination; do not blindly relay the incoming authorization header. Credential encryption at rest does not make arbitrary workflow editors or community nodes trustworthy. Restrict editor/integration access and egress, and review exports/logs before sharing. <a href="https://docs.n8n.io/integrations/builtin/credentials/httprequest/" target="_blank" rel="noreferrer">HTTP Request credentials</a>, <a href="https://docs.n8n.io/integrations/builtin/credentials/webhook/" target="_blank" rel="noreferrer">Webhook credentials</a>.</p><h2 id="node-recipe-and-idempotency" tabindex="-1"><span class="hub-section-number">3 </span>Node recipe and idempotency <a class="header-anchor" href="#node-recipe-and-idempotency" aria-label="Permalink to “3 Node recipe and idempotency”">​</a></h2><table tabindex="0"><thead><tr><th>Node</th><th>Parameters / observable handoff</th></tr></thead><tbody><tr><td>Webhook</td><td>POST, test listener, configured inbound Header Auth, explicit response mode</td></tr><tr><td>Normalize (Code/Edit Fields)</td><td>Accept only event/source/revision/action; cap batch/items/strings and retain correlation</td></tr><tr><td>If</td><td>Supported action <code>refresh</code>; invalid events never enter HTTP Request</td></tr><tr><td>HTTP Request</td><td>Fixed reviewed service URL; configured outbound credential; JSON body from the normalized current item; finite timeout; no arbitrary redirect destination</td></tr><tr><td>Respond to Webhook</td><td>Return projected status/receipt tied to the same event; do not return credentials/raw service errors</td></tr><tr><td>Error handling path</td><td>Classify failure and retain safe event/execution references; no email/message node is necessary</td></tr></tbody></table><p>Use a stable business event/operation ID independent of the n8n execution ID. A retried execution gets another execution identity but may represent the same event. The service binds the event ID to exact command bytes and current authorized scope: same event/same command returns the original receipt, changed command conflicts. A timeout after commit is uncertain; reconcile/replay the same key under that service contract. n8n retries alone cannot implement exactly-once external effects.</p><h2 id="connection-to-rag-and-agents" tabindex="-1"><span class="hub-section-number">4 </span>Connection to RAG and agents <a class="header-anchor" href="#connection-to-rag-and-agents" aria-label="Permalink to “4 Connection to RAG and agents”">​</a></h2><p>Replace the synthetic refresh receipt with a durable authorized ingestion job only after P-334 has source versions, tombstones and derivative cleanup. The request should reference the source; the service loads authorized bytes. A refresh callback must not resurrect a deleted revision or let a source URL select arbitrary egress.</p><p>For P-335, n8n may notify an owned UI that a proposal awaits review, but must not turn model output or a generic Wait/form response into trusted approval automatically. The application stores the exact authenticated command-bound decision and receipt. The local workbench demonstrates only transformation and adapter contracts, not these complete integrations.</p><p><a href="./../../practice/applied-ai/n8n-integration.html">Separate practice and evidence</a> · <a href="./operations.html">Errors and deployment</a></p>',15))])}const y=n(l,[["render",h]]);export{g as __pageData,y as default};
